 const baseBits=lines.map(x=>x%2),moving=lines.map((x,i)=>x===6||x===9?i+1:0).filter(Boolean),primary=hexagramFromBits(baseBits),changed=hexagramFromBits(changedBits(baseBits,moving));
 const timestamp=new Date().toISOString(),tz=Intl.DateTimeFormat().resolvedOptions().timeZone||'';
 const dayStem=window.FateEngine?.timezoneDayStem?.(timestamp,tz)?.stem||null;
