 coin={lines,moving,hex:primary.title,primary,changed,time:timestamp,tz,najia};
 $('coinResult').innerHTML=`<b>${safe(primary.title)}</b>${uiHex(lines)}<div class="notice">動爻：${moving.length?moving.join('、'):'無'} · 之卦 ${safe(changed.title)}<br>爻數（下→上）${lines.join(' · ')}；日期以 ${safe(tz||'未知時區')} 計算。</div>${coinDetailsView()}`;
