function timeBranch(hour){return mod(Math.floor((hour+1)/2),12)}
function castPlum(){const now=new Date(),tz='Asia/Taipei',parts=new Intl.DateTimeFormat('en-u-ca-chinese',{timeZone:tz,year:'numeric',month:'numeric',day:'numeric'}).formatToParts(now),get=t=>parts.find(x=>x.type===t)?.value,year=Number(get('relatedYear')),month=parseInt(get('month'),10),day=Number(get('day')),hour=Number(new Intl.DateTimeFormat('en-GB',{timeZone:tz,hour:'2-digit',hourCycle:'h23'}).format(now));if(!year||!month||!day){$('plumResult').textContent='農曆無法讀取，停止起卦';return}const yr=mod(year-1984,12)+1,h=timeBranch(hour)+1,a=yr+month+day,b=a+h,up=mod(a-1,8),low=mod(b-1,8),move=mod(b-1,6)+1,bits=[...TRIBITS[low],...TRIBITS[up]],primary=hexagramFromBits(bits),changed=hexagramFromBits(changedBits(bits,[move])),mutual=hexagramFromBits([...bits.slice(1,4),...bits.slice(2,5)]);plum={up:TRIGRAM[up],low:TRIGRAM[low],move,primary,changed,mutual,time:now.toISOString(),input:`年支序數 ${yr}、農曆月 ${month}、日 ${day}、時支序數 ${h}`,tz};$('plumResult').innerHTML=`<b>${safe(primary.title)}</b><p>第 ${move} 爻動 · 互卦 ${safe(mutual.title)} · 之卦 ${safe(changed.title)}</p><p class="notice">${safe(plum.input)} · ${tz}</p>`;renderQuick();if(generated)renderReport(false)}
