function reportMarkup(c){const reading=window.FateInterpretation.consultation(c,readingContext(),{coin,plum,tarotDrawn},weights);return `<div class="consult-report-head"><span>合參 · ${safe(c.p.iso)}</span><div class="report-edit-actions"><button type="button" class="btn btn-soft" data-report-birth>出生資料</button><button type="button" class="btn btn-soft" data-change-question>換個問題 ↗</button></div></div>${window.FateInterpretation.renderConsultation(reading)}<!--advanced-start--><details class="advanced-report"><summary>命盤與詳細計算</summary><button type="button" class="btn btn-soft" data-advanced-weights>調整流派權重</button>${technicalReportMarkup(c)}</details><!--advanced-end-->`;}
function renderReport(scroll=true){const p=dateParts($('dob').value);if(!p){gameToast('先輸入有效的西元生日');focusBirthday();return false}const c=compute(p);if(weightMode==='auto')weights=window.FateInterpretation.recommend(readingContext(),c.ready).weights;c.coverage=Object.entries(weights).reduce((n,[id,w])=>n+(c.ready[id]?w:0),0);renderWeights(c);lastComputed=c;generated=true;$('reportInner').innerHTML=reportMarkup(c);$('shareFeedback').textContent='';$('reportInner').querySelector('[data-takeaway]')?.addEventListener('click',()=>showView('finish'));$('reportInner').querySelector('[data-report-birth]')?.addEventListener('click',()=>showView('birth'));for(const b of $('reportInner').querySelectorAll('[data-change-question]'))b.onclick=()=>showView('home');$('reportInner').querySelector('[data-random-perspective]')?.addEventListener('click',()=>{showView('album');spinDiscovery()});$('reportInner').querySelector('[data-advanced-weights]')?.addEventListener('click',()=>showView('weights'));if(scroll){showView('report',false);window.scrollTo?.({top:0,behavior:'instant'})}}
function exportReport(){if(!dateParts($('dob').value))return;if(!generated)renderReport(false);let html=`<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>合參命理報告 - ${safe($('dob').value)}</title><style>${REPORT_CSS} ${INTERPRETATION_CSS} body{background:#f4f1e9;color:#293733;max-width:1040px;margin:auto;padding:32px}body:before{display:none}.report-sheet{color:#293733}.report-cover h2{color:#293733}.report-item{color:#293733}.notice,.muted{color:#768172}a{color:#3f6951}@media print{body{padding:0}}</style></head><body class="report-export">${$('reportInner').innerHTML.replace(/<!--advanced-start-->[\s\S]*?<!--advanced-end-->/g,'').replace(/<img\b[^>]*>/g,'').replace(/<button\b[^>]*>[\s\S]*?<\/button>/g,'').replace(/<details(?![^>]*\bopen\b)/g,'<details open')}</body></html>`;const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`合參命理報告_${$('dob').value}.html`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function encodeState(obj){const str=encodeURIComponent(JSON.stringify(obj));return btoa(str).replace(/\+/g,'-').replace(/\//g,'_').replace(/=/g,'')}
function decodeState(b){const norm=b.replace(/-/g,'+').replace(/_/g,'/');return JSON.parse(decodeURIComponent(atob(norm)))}
function publicHost(){return location.protocol==='https:'&&!['localhost','127.0.0.1'].includes(location.hostname)}
function restoreCoin(lines,originalTime,tz){
 const baseBits=lines.map(n=>n%2),moving=lines.flatMap((n,i)=>(n===6||n===9)?[i+1]:[]);
 const primary=hexagramFromBits(baseBits),changed=hexagramFromBits(changedBits(baseBits,moving));
 const time=typeof originalTime==='string'&&/^\d{4}-\d\d-\d\dT/.test(originalTime)?originalTime:null;
 const dayStem=time&&tz?window.FateEngine?.timezoneDayStem?.(time,tz)?.stem:null;
 const najia=window.FateEngine?.najia?.(lines,dayStem)||null;
 return {lines:[...lines],moving,hex:primary.title,primary,changed,time,tz:tz||null,najia};
}
function restorePlum(data){
 const ui=TRIGRAM.indexOf(data.up),li=TRIGRAM.indexOf(data.low),move=data.move;
 if(ui<0||li<0||!Number.isInteger(move)||move<1||move>6)return null;
 const hexBits=[...TRIBITS[li],...TRIBITS[ui]];
 const primary=hexagramFromBits(hexBits),changed=hexagramFromBits(changedBits(hexBits,[move]));
 const mutual=hexagramFromBits([...hexBits.slice(1,4),...hexBits.slice(2,5)]);
 const time=typeof data.time==='string'&&!Number.isNaN(Date.parse(data.time))?data.time:null;
 return {up:TRIGRAM[ui],low:TRIGRAM[li],move,primary,changed,mutual,time,input:'依分享的上下卦與動爻重建；原始時間推導未經驗證',tz:'分享連結'};
}
function share(){
 if(!dateParts($('dob').value))return;
 if(!generated)renderReport(false);
 if(!publicHost()){$('shareFeedback').textContent='目前尚無可公開分享的線上網址。請先部署到 HTTPS 網站。';return}
 const advanced={time:$('birthtime').value,tz:$('birthtz').value,gender:$('gender').value,lat:$('latitude').value,lon:$('longitude').value,fold:$('timefold').value};
 if((advanced.time||advanced.tz||advanced.gender||advanced.lat||advanced.lon||$('readingQuestion').value.trim())&&!confirm('此分享連結會包含生日、你填寫的問題，以及已提供的出生時地。任何拿到網址的人都可查看。確認分享嗎？'))return;
 const state={v:1,app:VERSION,advanced:(advanced.time||advanced.tz||advanced.gender||advanced.lat||advanced.lon)?advanced:null,birth:$('dob').value,topic:$('topic').value,question:$('readingQuestion').value.slice(0,300),year:Number($('readingYear').value),weightMode,weights,
 coin:coin?{lines:coin.lines,time:coin.time,tz:coin.tz}:null,
 tarot:tarotDrawn?{cards:tarotDrawn.cards,spread:tarotDrawn.spread,time:tarotDrawn.time}:null,
 plum:plum?{up:plum.up,low:plum.low,move:plum.move,time:plum.time}:null};
 const data=encodeState(state),url=location.href.split('#')[0]+'#report='+data;
 if(url.length>8000){$('shareFeedback').textContent='資料過長，請改用下載HTML報告。';return}
 history.replaceState({...history.state},'',url);
 const showLink=(message)=>{
  $('shareFeedback').replaceChildren();
  const txt=document.createElement('span');txt.textContent=message+'　分享連結含有生日，收到連結的人可查看。';
  const field=document.createElement('input');field.type='text';field.readOnly=true;field.value=url;field.setAttribute('aria-label','報告分享網址');field.className='share-link-field';
  $('shareFeedback').append(txt,field);
 };
 if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url)
   .then(()=>showLink('已複製可分享的報告網址。'))
   .catch(()=>showLink('可複製下方分享網址。'));
 else showLink('可複製下方分享網址。');
}
function loadUrl(){
 const h=location.hash;if(!h.startsWith('#report=')||h.length>12000)return;
 try{
  const s=decodeState(h.slice(8));if(s?.v!==1||!dateParts(s.birth))return;
  $('dob').value=s.birth;
  if(['overview','career','love','wealth','year'].includes(s.topic))$('topic').value=s.topic;
  if(typeof s.question==='string')$('readingQuestion').value=s.question.slice(0,300);
  if(Number.isInteger(s.year)&&s.year>=1900&&s.year<=2200){if(!Array.from($('readingYear').options).some(o=>Number(o.value)===s.year)){$('readingYear').innerHTML+=`<option value="${s.year}">${s.year} 年</option>`;}$('readingYear').value=String(s.year);}
  updateTopicBrief();
  if(s.weightMode==='manual')weightMode='manual';
  if(s.weights&&Object.keys(DEFAULT).every(k=>Number.isInteger(s.weights[k])&&s.weights[k]>=0&&s.weights[k]<=100)&&Object.values(s.weights).reduce((a,b)=>a+b,0)===100)weights={...s.weights};
  if(s.advanced&&typeof s.advanced==='object'){
   if(/^\d\d:\d\d$/.test(s.advanced.time||''))$('birthtime').value=s.advanced.time;
   if(Array.from($('birthtz').options).some(o=>o.value&&o.value===s.advanced.tz))$('birthtz').value=s.advanced.tz;
   if(['male','female'].includes(s.advanced.gender))$('gender').value=s.advanced.gender;
   for(const [k,id,max] of [['lat','latitude',90],['lon','longitude',180]])if(s.advanced[k]!==''&&Number.isFinite(Number(s.advanced[k]))&&Math.abs(Number(s.advanced[k]))<=max)$(id).value=s.advanced[k];
   if(['earlier','later'].includes(s.advanced.fold))$('timefold').value=s.advanced.fold;
  }
  if(s.coin&&Array.isArray(s.coin.lines)&&s.coin.lines.length===6&&s.coin.lines.every(x=>[6,7,8,9].includes(x)))coin=restoreCoin(s.coin.lines,s.coin.time,s.coin.tz);
  if(s.tarot)tarotDrawn=window.FateEngine?.validateDraw?.(s.tarot)||null;
  if(tarotDrawn)showTarot();
  if(s.plum)plum=restorePlum(s.plum);
  if(coin)$('coinResult').innerHTML='<b>'+safe(coin.primary.title)+'</b>'+uiHex(coin.lines)+coinDetailsView();if(plum)$('plumResult').innerHTML='<b>'+safe(plum.primary.title)+'</b><p>第 '+plum.move+' 爻動 · 之卦 '+safe(plum.changed.title)+'</p>';renderQuick();renderReport(false);showView('report',false);
  if(s.app&&s.app!==VERSION){$('shareFeedback').textContent='此連結由舊版程式產生，已依目前算法重新計算；結果可能不同。'}
 }catch(e){/* 無效分享連結不採用 */}
}
