function openChart(id){if(!$('chartDialog').open&&!routeRestoring){rememberRoute();history.pushState?.({...history.state,fateRoute:{view:currentView,chart:id,y:window.scrollY||0}},'',location.href);}openChartContent(id);}
function heroArt(){const tick=Array.from({length:72},(_,i)=>{let a=i*5*Math.PI/180,r=i%6===0?189:197;return `<line x1="${220+r*Math.cos(a)}" y1="${220+r*Math.sin(a)}" x2="${220+203*Math.cos(a)}" y2="${220+203*Math.sin(a)}" stroke="#aa8d5a" opacity="${i%6===0?.8:.28}"/>`}).join('');const glyphs=ZODIAC_GLYPHS.map((x,i)=>{let a=(i*30-75)*Math.PI/180;return `<text x="${220+169*Math.cos(a)}" y="${226+169*Math.sin(a)}" text-anchor="middle" font-size="21" fill="#8c6eac">${x}</text>`}).join('');return `<svg class="hero-sky" viewBox="0 0 440 440"><defs><radialGradient id="halo"><stop stop-color="#e4d7f6" stop-opacity=".65"/><stop offset="1" stop-color="#fffbf6" stop-opacity="0"/></radialGradient></defs><circle cx="220" cy="220" r="210" fill="url(#halo)"/><g fill="none" stroke="#ad9162"><circle cx="220" cy="220" r="203" opacity=".55"/><circle cx="220" cy="220" r="186" opacity=".35"/><circle cx="220" cy="220" r="146" opacity=".55"/><circle cx="220" cy="220" r="139" opacity=".35"/><circle cx="220" cy="220" r="111" opacity=".45" stroke-dasharray="2 9"/><ellipse cx="220" cy="220" rx="130" ry="64" transform="rotate(-35 220 220)" opacity=".35"/><ellipse cx="220" cy="220" rx="130" ry="64" transform="rotate(35 220 220)" opacity=".35"/><path d="M220 72V368M72 220H368M115 115L325 325M115 325L325 115" opacity=".22"/></g>${tick}${glyphs}<g stroke="#bf8b49" fill="none"><path d="M220 139L238 203L301 220L238 238L220 301L202 238L139 220L202 203Z"/><path d="M220 160L228 212L280 220L228 228L220 280L212 228L160 220L212 212Z" opacity=".55"/></g><circle cx="220" cy="220" r="6" fill="#bb8b4c"/><circle cx="315" cy="174" r="5" fill="#a28abd"/><circle cx="128" cy="267" r="3" fill="#bb8b4c"/><text x="220" y="30" text-anchor="middle" font-size="8" letter-spacing="3" fill="#987744">N</text><text x="220" y="426" text-anchor="middle" font-size="8" letter-spacing="4" fill="#8d7b96">TWELVE SYSTEMS · ONE YOU</text></svg><div class="hero-side">FATE ATLAS / EST. 2026</div>`;}
function wheel(c,mode='western',paper=false){const sky=c.sky,live=sky.status==='ok',sid=mode==='vedic',points=live?sky.points:[{lon:c.bazi.lambda,sidereal:mod(c.bazi.lambda-c.aya,360),glyph:'☉'}],ref=live&&sky.axes?mod(sky.axes.asc-(sid?sky.aya:0),360):0,color=paper?'#476b50':'var(--chart-ink,#4a7d9e)',muted=paper?'#7e8f7c':'var(--chart-line,#b8cbd9)';const pos=(lon,r)=>{let a=(lon-ref)*Math.PI/180;return [160-r*Math.cos(a),160+r*Math.sin(a)]};let art='';for(let i=0;i<12;i++){let a=pos(i*30,110),b=pos(i*30,143),t=pos(i*30+15,128);art+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${muted}" stroke-width=".7"/><text x="${t[0]}" y="${t[1]+6}" text-anchor="middle" font-size="19" fill="${color}">${ZODIAC_GLYPHS[i]}</text>`;}if(live&&!sid)for(const a of sky.aspects.slice(0,16)){let p=pos(points[a.ai].lon,70),q=pos(points[a.bi].lon,70);art+=`<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${a.angle===90||a.angle===180?'#c28077':'#77a396'}" opacity=".5" stroke-width=".65"/>`;}for(let i=0;i<points.length;i++){const p=points[i],lon=sid?p.sidereal:p.lon,a=pos(lon,105),b=pos(lon,78+i%3*10);art+=`<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${muted}" stroke-width=".5"/><circle cx="${a[0]}" cy="${a[1]}" r="1.6" fill="${color}"/><text x="${b[0]}" y="${b[1]+4}" text-anchor="middle" fill="${color}" font-size="13">${p.glyph}</text>`;}if(live&&sky.axes){const x=pos(mod(sky.axes.asc-(sid?sky.aya:0),360),146);art+=`<text x="${x[0]+9}" y="${x[1]-7}" font-size="7" fill="${color}">ASC</text>`;}return `<svg class="chart-svg zodiac-svg" viewBox="0 0 320 320" role="img" aria-label="${live?'行星星盤':'太陽日期摘要'}"><g fill="none" stroke="${muted}"><circle cx="160" cy="160" r="151" stroke-dasharray="1 4"/><circle cx="160" cy="160" r="143"/><circle cx="160" cy="160" r="110"/><circle cx="160" cy="160" r="67" stroke-dasharray="1 5"/></g>${art}<text x="160" y="163" text-anchor="middle" font-size="8" fill="${color}" letter-spacing="1">${live?'NATAL CHART':'DATE ONLY'}</text></svg>`;}
function vedicArt(c){const ready=c.sky.status==='ok',points=ready?c.sky.points:[],order=[11,0,1,2,10,-1,-1,3,9,-1,-1,4,8,7,6,5];let cells='';order.forEach((sign,i)=>{if(sign<0)return;const x=i%4*64+3,y=Math.floor(i/4)*64+3;const p=points.filter(p=>Math.floor(p.sidereal/30)===sign);cells+=`<rect x="${x}" y="${y}" width="62" height="62" fill="none" stroke="#b89a5e" stroke-opacity=".45"/><text x="${x+7}" y="${y+14}" fill="#896c35" font-size="8">${ZODIAC_SHORT[sign]}</text><text x="${x+31}" y="${y+39}" fill="#976b2f" text-anchor="middle" font-size="12">${p.map(p=>p.glyph).join(' ')}${ready&&c.sky.axes&&Math.floor(mod(c.sky.axes.asc-c.sky.aya,360)/30)===sign?' AS':''}</text>`;});return `<svg class="chart-svg" viewBox="0 0 262 262" role="img" aria-label="南印度固定星座命盤">${cells}<text x="131" y="118" text-anchor="middle" font-size="16" fill="#976b2f">ज्योतिष</text><text x="131" y="141" text-anchor="middle" font-size="9" fill="#93733b">${ready?'D1 · RASHI':'等待出生時刻'}</text><text x="131" y="159" text-anchor="middle" font-size="7" fill="#8b764c">SIDEREAL / LAHIRI ≈</text></svg>`;}
function nineArt(c){const n=c.nine?.star;if(!n)return emptyArt('九星','節氣交界需時間');const nums=[4,9,2,3,5,7,8,1,6];return `<svg class="chart-svg" viewBox="0 0 270 270" role="img" aria-label="以本命星 ${n} 入中宮的九星盤"><text x="135" y="13" text-anchor="middle" fill="#567e53" font-size="8">南 S</text>${nums.map((v,i)=>{const x=25+i%3*74,y=25+Math.floor(i/3)*74,star=mod(v+n-6,9)+1;return `<rect x="${x}" y="${y}" width="72" height="72" rx="2" fill="${i===4?'#d8edc388':'none'}" stroke="#86a579" stroke-opacity=".5"/><text x="${x+36}" y="${y+46}" text-anchor="middle" font-family="Georgia,serif" font-size="29" fill="${i===4?'#467e4d':'#739067'}">${star}</text>`}).join('')}<text x="135" y="265" text-anchor="middle" fill="#567e53" font-size="8">北 N · 本命入中宮示意</text></svg>`;}
function plumArt(){if(!plum)return emptyArt('☷','等待一個問事的時刻');return `<div class="iching-graphic"><div class="iching-line-stack">${uiHex([...TRIBITS[TRIGRAM.indexOf(plum.low)],...TRIBITS[TRIGRAM.indexOf(plum.up)]].map(v=>v?7:8))}</div><strong>${safe(plum.primary.title)}</strong><small>互 ${safe(plum.mutual.title)} · 第 ${plum.move} 爻動</small></div>`;}
function liuArt(){if(!coin?.najia)return emptyArt('☰','起卦後展開納甲關係');return `<svg class="chart-svg" viewBox="0 0 270 240" role="img" aria-label="六爻納甲與世應">${coin.najia.lines.slice().reverse().map((l,i)=>{const y=28+i*36;return `<text x="12" y="${y}" fill="#8f7744" font-size="11">${l.spirit||'—'}</text><path d="M65 ${y-4}H${l.bits?146:98}${l.bits?'':`M115 ${y-4}H146`}" stroke="#9e7d36" stroke-width="7"/><text x="160" y="${y}" fill="#9e7d36" font-size="11">${l.relative} ${l.branch} ${l.mark}</text>`;}).join('')}</svg>`;}
function birthArt(c){const ix=c.tarot.major%22;return `<svg class="chart-svg" viewBox="0 0 260 260" role="img" aria-label="塔羅生日牌 ${safe(TAROT_NAMES[ix])}"><rect x="62" y="15" width="136" height="229" rx="5" fill="#f0e1fa88" stroke="#b593cb"/><rect x="69" y="22" width="122" height="215" rx="2" fill="none" stroke="#c6acd7" stroke-opacity=".5"/><text x="130" y="51" text-anchor="middle" fill="#8a60a7" font-size="11">${ix===0?'0':ix}</text><circle cx="130" cy="118" r="38" fill="none" stroke="#b28bc8"/><path d="M130 69L144 105L182 118L144 132L130 169L116 132L78 118L116 105Z" fill="none" stroke="#9a70b7"/><text x="130" y="204" text-anchor="middle" fill="#775191" font-size="17">${safe(TAROT_NAMES[ix])}</text><text x="130" y="223" text-anchor="middle" fill="#917aa6" font-size="7" letter-spacing="2">BIRTH ARCHETYPE</text></svg>`;}
function mayaArt(c){const tone=Number(c.my.tz.split(' ')[0]);return `<svg class="chart-svg" viewBox="0 0 270 270" role="img" aria-label="傳統卓爾金 ${safe(c.my.tz)}"><g fill="none" stroke="#7db19a"><circle cx="135" cy="135" r="111" stroke-opacity=".3"/><circle cx="135" cy="135" r="88" stroke-opacity=".6"/><circle cx="135" cy="135" r="67" stroke-opacity=".3"/>${Array.from({length:20},(_,i)=>{let a=i*Math.PI/10;return `<path d="M${135+93*Math.cos(a)} ${135+93*Math.sin(a)}L${135+108*Math.cos(a)} ${135+108*Math.sin(a)}" stroke-width="${i===mod(c.my.days+19,20)?4:1}"/>`}).join('')}</g><text x="135" y="132" text-anchor="middle" font-family="Georgia,serif" font-size="49" fill="#3a9276">${tone}</text><text x="135" y="157" text-anchor="middle" font-size="12" fill="#518d73">${safe(c.my.tz.split(' ').slice(1).join(' '))}</text><text x="135" y="255" text-anchor="middle" font-size="9" fill="#5a8c74">${c.my.long} · GMT 584283</text></svg>`;}
function emptyArt(symbol,text){return `<div class="chart-empty"><strong>${symbol}</strong><span>${text}</span><small>資料完整時，圖譜會在此展開</small></div>`;}
function visualFor(id,c,paper=false){const map={western:()=>wheel(c,'western',paper),vedic:()=>vedicArt(c),ziwei:()=>palaceDiagram(c),bazi:()=>baziGraphic(c),iching:hexGraphic,tarotDraw:tarotGraphic,numerology:()=>numberGraphic(c),meihua:plumArt,liuyao:liuArt,nineStar:()=>nineArt(c),tarotBirth:()=>birthArt(c),maya:()=>mayaArt(c)};return map[id]();}
function renderVisuals(c){$('visualGrid').innerHTML=COLLECTION.filter(m=>atlasFilter==='all'||m.group===atlasFilter).map(m=>{const i=COLLECTION.indexOf(m),state=m.id==='maya'?'僅供曆法參照，不參與解讀輪盤':c?methodState(MODULES.find(x=>x.id===m.id),c)[1]:'填生日後開始解讀';return `<article class="visual-card v-${m.id}" data-chart="${m.id}"><button type="button" class="visual-open" data-open="${m.id}" aria-label="選擇${m.name}進行解讀"></button><div class="school-photo"><img src="./assets/schools/${m.id}.webp" alt="${safe(SCHOOL_ART[m.id])}" loading="lazy" width="1200" height="800"><span class="school-cue">${SCHOOL_CUES[m.id]}</span></div>${explored.has(m.id)?'<span class="explored-label">✦ 已探索</span>':''}<div class="visual-heading"><span class="visual-number">${String(i+1).padStart(2,'0')}</span><div><span class="visual-latin">${m.latin}</span><h3>${m.name}</h3></div></div><div class="visual-bottom"><div><b>${m.title}</b><small>${safe(state)}</small></div><span class="visual-link" aria-hidden="true">↗</span></div></article>`}).join('');$('visualGrid').querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>{if(!lastComputed){focusBirthday();return;}try{if(!lastComputed.ready[b.dataset.open]&&window.FateDiscovery.actionFor(b.dataset.open)!=='birth')runReading(b.dataset.open);openChart(b.dataset.open)}catch(e){gameToast(String(e.message||e))}}));}
function table(head,rows){return `<div class="data-scroll"><table class="data-table"><thead><tr>${head.map(x=>`<th>${safe(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${safe(x??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function stats(items){return `<div class="detail-stats">${items.map(([k,v])=>`<div class="detail-stat"><small>${safe(k)}</small><b>${safe(v)}</b></div>`).join('')}</div>`;}
function skyDetails(c,sid=false){const s=c.sky;if(s.status!=='ok')return `<div class="detail-lead">${safe(s.reason)}</div><p class="detail-note">生日摘要仍可使用。新增出生時間、時區後可計算十顆行星；加入座標後可計算上升與整宮宮位。</p><button class="btn btn-primary" data-edit-birth>加入出生資訊 ↗</button>`;let rows=s.points.map(p=>[p.glyph+' '+p.name,SKY().signText(sid?p.sidereal:p.lon),p.retrograde?'逆行':'順行',sid?p.vedicHouse:p.house]);const summary=sid?[['恆星月宿',s.vedic.nakshatra.split(' ')[0]],['Pada',s.vedic.pada+'/4'],['歲差（近似）',s.aya.toFixed(2)+'°']]:[['太陽',SKY().signText(s.points[0].lon)],['月亮',SKY().signText(s.points[1].lon)],['上升',s.axes?SKY().signText(s.axes.asc):'需出生座標'],['天頂 MC',s.axes?SKY().signText(s.axes.mc):'需出生座標']];return `<div class="detail-lead">${sid?'以月亮為起點，展開恆星之旅。':'一個時刻，十顆行星的座標。'}</div>${stats(summary)}<p class="detail-note">UTC ${safe(s.utc)} · ${safe(s.civil.timezone)}<br>${safe(s.locationReason)}${sid?'<br>Lahiri 歲差為近似模型，非 Swiss Ephemeris；月宿與分盤交界需另校核。':''}</p>${table(['行星',sid?'恆星黃道':'熱帶黃道','動態','整宮'],rows)}${sid?`<h3>27 月宿 · D9 分盤</h3><p class="detail-note">${safe(s.vedic.nakshatra)} · 第 ${s.vedic.pada} 足 · 主星 ${s.vedic.lord}${s.vedic.nearBoundary?' · 接近交界，請以專業星曆複核':''}</p>${table(['行星','D9 Navamsa'],s.points.slice(0,7).map(p=>[p.name,SKY().signText(p.navamsa)]))}<p class="detail-note">羅睺 ${SKY().signText(s.vedic.rahu)} · 計都 ${SKY().signText(s.vedic.ketu)}（平交點近似）</p><h3>Vimshottari 大運</h3><p class="detail-note">依月宿剩餘比例起運；年長採 365.2425 天。日期為近似研究用。</p><div class="dasha-timeline">${s.vedic.dasha.map(p=>`<div class="dasha-period"><b>${p.lord}</b><span>${p.start} → ${p.end}</span></div>`).join('')}</div>`:`${s.axes?'<h3>十二整宮宮界</h3>'+table(['宮位','起點'],Array.from({length:12},(_,i)=>[i+1,SKY().signText(mod(Math.floor(s.axes.asc/30)*30+i*30,360))])):''}<h3>本命主要相位</h3>${table(['行星 A','相位','行星 B','容許度'],s.aspects.map(a=>[a.a,a.name+' '+a.angle+'°',a.b,a.orb.toFixed(2)+'°']))}<p class="detail-note">合／刑／拱／沖容許 6°；六合 4°。相位只呈現幾何關係。</p><h3>行運比較</h3><div class="field"><label for="transitDate">比較日期（12:00 UTC）</label><input id="transitDate" type="date" value="${new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}"></div><div id="transitData"></div>`}`;}
function chartDetails(id,c){if(['western','vedic'].includes(id))return skyDetails(c,id==='vedic');if(id==='ziwei'){const z=c.ziwei;if(z.status!=='ok')return `<div class="detail-lead">${safe(z.reason)}</div><p class="detail-note">紫微使用 iztro v2.6.5。缺少時辰時不推測命宮。</p><button class="btn btn-primary" data-edit-birth>加入出生資訊 ↗</button>`;return `<div class="detail-lead">十二宮，各有星光。</div><p class="detail-note">${safe(z.notes)}</p><div class="ziwei-grid">${z.palaces.map(p=>`<article class="ziwei-cell"><b>${safe(p.name)} · ${safe(p.stem+p.branch)}</b><p>${p.stars.map(s=>safe(s.name)+' '+safe(s.brightness)+(s.mutagen?' · 化'+safe(s.mutagen):'')).join('、')||'無主星'}</p><small>${p.minor.map(safe).join(' · ')}<br>大限 ${safe(p.decade?.range||'—')}</small></article>`).join('')}</div>`;}
 if(id==='bazi')return `<div class="detail-lead">${safe(c.bazi.year||'？')} · ${safe(c.bazi.month||'？')} · ${safe(c.bazi.day)} · ${safe(c.baziExtra?.hour||'？')}</div><p class="detail-note">日主 ${safe(c.bazi.dayMaster)}。採民用時間零時換日；未校正真太陽時。${safe(c.baziExtra?.reason||'')}</p>${table(['柱','天干十神','藏干與十神'],(c.baziExtra?.godInfo||[]).map(x=>[x.pillar,x.stemTenGod,x.hidden.join('、')]))}${c.luck?`<h3>大運 · ${c.luck.forward?'順行':'逆行'}</h3><p class="detail-note">約 ${c.luck.age.toFixed(2)} 歲起運；採三天折一歲，距離相鄰節點計算。</p>${table(['大運','起始歲數','結束歲數'],c.luck.periods.map(x=>[x.pillar,x.from.toFixed(2),x.to.toFixed(2)]))}`:'<p class="detail-note">補上時間、時區及傳統性別參數後可計算大運。喜用神不以固定字數比例推斷。</p>'}`;
 if(id==='numerology')return `<div class="detail-lead">你的生命道路數：${c.num.life}</div>${stats([['生日數',c.num.birthday],['態度數',c.num.attitude],['個人年',c.num.personalYear]])}<h3>四個頂峰與挑戰</h3>${table(['階段','頂峰','挑戰'],c.num.peaks.map((v,i)=>[i+1,v,c.num.challenges[i]]))}<p class="detail-note">${c.num.lifeSum} → ${c.num.life}。本版將所有數字歸約至 1–9，未保留 11／22／33 主數；這是明確選定的算法流派。</p>`;
 if(id==='nineStar')return `<div class="detail-lead">${safe(c.nine?.name||'節氣交界待確認')}</div>${stats([['本命星',c.nine?.star||'—'],['月命星',c.nine?.monthName||'待節氣確認'],['當年中宮',c.nine?.annual||'—']])}<p class="detail-note">以立春換年、十二節換月；本命盤為本命星入中宮的九宮示意，南方在上。本版不提供未校準的日命與旅行吉凶斷語。</p>`;
 if(id==='tarotBirth')return `<div class="detail-lead">${safe(TAROT_NAMES[c.tarot.major%22])} / ${safe(TAROT_NAMES[c.tarot.minor%22])}</div>${stats([['生日主牌',c.tarot.major%22],['靈魂牌',c.tarot.minor%22],['年度牌',c.tarot.yearCard]])}<p class="detail-note">${safe(c.tarot.calc)}。數字 22 對應愚者 0；年度牌以當年取代出生年，採相同歸約規則。生日牌與隨機抽牌是兩種不同方法。</p>`;
 if(id==='maya')return `<div class="detail-lead">${safe(c.my.tz)}</div>${stats([['長紀曆',c.my.long],['Haab',c.my.haab],['JDN',c.my.jdn]])}<p class="detail-note">使用傳統 GMT 584283 對應。2012-12-21 對應 13.0.0.0.0、4 Ajaw、3 Kʼankʼin；不混入現代 Dreamspell 的 Kin 系統。</p>`;
 if(id==='tarotDraw')return tarotDrawn?`<div class="detail-lead">${tarotDrawn.spread===10?'塞爾特十字':tarotDrawn.spread===3?'三張牌陣':'單張牌'}</div><div class="tarot-cards">${window.FateEngine.tarotView(tarotDrawn).map((p,i)=>`<article class="tarot-card"><span class="number">${safe(spreadName(tarotDrawn.spread,i))}</span><b>${safe(p.name)}</b><small>${p.reversed?'逆位':'正位'}</small><p>${safe(p.meaning)}</p></article>`).join('')}</div><p class="detail-note">${safe(tarotDrawn.time)} · 78 張完整牌組；不重複抽取。牌義提供反思角度，不判定未來事件。</p>`:`<div class="detail-lead">為當下留一個提問。</div><p class="detail-note">請選擇牌陣，從 78 張牌中獨立抽取。</p><div class="dialog-actions"><button class="btn btn-soft" data-dialog-draw="1">單張牌</button><button class="btn btn-primary" data-dialog-draw="3">三張牌</button><button class="btn btn-soft" data-dialog-draw="10">塞爾特十字</button></div>`;
 if(id==='meihua')return plum?`<div class="detail-lead">${safe(plum.primary.title)}</div>${stats([['互卦',plum.mutual.title],['之卦',plum.changed.title],['動爻',plum.move]])}<p class="detail-note">${safe(plum.input)} · ${safe(plum.time)}<br>${safe(plum.tz)}；體為未動三爻之卦、用為含動爻之卦。</p>${stats([['體卦',plum.move<=3?plum.up:plum.low],['用卦',plum.move<=3?plum.low:plum.up]])}`:`<div class="detail-lead">讓當下的時刻，成為起點。</div><p class="detail-note">以臺北時區的農曆年月日與時支起卦，閏月沿用月份數，不以生日代替起卦時刻。</p><button class="btn btn-primary" data-dialog-plum>現在起卦 ↗</button>`;
 return coin?`<div class="detail-lead">${safe(coin.primary.title)}</div>${uiHex(coin.lines)}${stats([['之卦',coin.changed.title],['動爻',coin.moving.join('、')||'無'],['八宮',coin.najia?.palace||'—']])}${coinDetailsView()}<p class="detail-note">${safe(coin.time)} · ${safe(coin.tz)}<br>三枚銅錢的 6／7／8／9 機率為 1／3／3／1；動爻為 6 或 9。</p>`:`<div class="detail-lead">先有提問，再讓六爻成形。</div><p class="detail-note">每爻獨立擲三枚硬幣，由下而上六次；與生日無關。</p><button class="btn btn-primary" data-dialog-coin>擲幣起卦 ↗</button>`;
}
function spreadName(n,i){return n===10?['現況','交叉／挑戰','根基','過去','意識目標','近期發展','自我位置','外在環境','希望與恐懼','可能走向'][i]:n===3?['過去／背景','現在／焦點','未來／反思方向'][i]:'當下的提醒';}
function openChartContent(id){const c=lastComputed;if(!c){focusBirthday();return;}if(c.ready[id]&&id!=='maya')recordExplore(id);const m=COLLECTION.find(m=>m.id===id);$('chartTitle').textContent=m.name;$('chartDialog').dataset.system=id;$('chartBody').innerHTML=readingMarkup(id,c);if(!$('chartDialog').open)$('chartDialog').showModal();for(const b of $('chartBody').querySelectorAll('[data-edit-birth]'))b.addEventListener('click',editBirthFromReading);for(const b of $('chartBody').querySelectorAll('[data-dialog-draw]'))b.onclick=()=>gameAction('tarot',b,()=>{drawTarot(+b.dataset.dialogDraw);openChart(id)});const coinButton=$('chartBody').querySelector('[data-dialog-coin]');if(coinButton)coinButton.onclick=()=>gameAction('coin',coinButton,()=>{castCoins();openChart(id)});const plumButton=$('chartBody').querySelector('[data-dialog-plum]');if(plumButton)plumButton.onclick=()=>gameAction('plum',plumButton,()=>{castPlum();openChart(id)});$('chartBody').querySelector('[data-edit-question]')?.addEventListener('click',()=>{showView('home',false);$('questionSettings').open=true;$('commonQuestions').scrollIntoView({behavior:'smooth',block:'center'})});$('chartBody').querySelector('[data-full-reading]')?.addEventListener('click',()=>{renderReport()});$('chartBody').querySelector('[data-read-again]')?.addEventListener('click',()=>{showView('album');spinDiscovery()});if($('transitDate')){const run=()=>{const t=SKY().transits(c.sky,$('transitDate').value);$('transitData').innerHTML=t?`<p class="detail-note">${safe(t.date)} · 行運對本命，依容許度排序</p>${table(['行運星','相位','本命星','差距'],t.aspects.slice(0,20).map(a=>[a.a,a.name,a.b,a.orb.toFixed(2)+'°']))}`:'';};$('transitDate').onchange=run;run();}}
const COMMON_QUESTIONS={love:['單身，怎麼增加認識對象的機會？','這段感情該怎麼相處？','分手後，還適合復合嗎？'],career:['現在適合換工作嗎？','工作卡住，該先改什麼？','想創業，現在怎麼開始？'],wealth:['最近財運要注意什麼？','怎麼增加收入機會？','目前適合增加支出嗎？'],overview:['最近最該把握什麼？','猶豫不決，下一步怎麼走？']};
function questionChoices(){const year=$('readingYear').value;return $('topic').value==='year'?[`${year} 年整體運勢如何？`,`${year} 年工作與感情要注意什麼？`]:COMMON_QUESTIONS[$('topic').value]||COMMON_QUESTIONS.overview;}
function syncQuestionChoices(){if(!$('commonQuestions'))return;const topic=$('topic').value;$('yearChoice').hidden=topic!=='year';document.querySelectorAll('[data-topic]').forEach(b=>{b.classList.toggle('active',b.dataset.topic===topic);b.setAttribute('aria-pressed',String(b.dataset.topic===topic))});$('commonQuestions').innerHTML=questionChoices().map(q=>`<button type="button" class="question-choice ${q===$('readingQuestion').value?'selected':''}" aria-pressed="${q===$('readingQuestion').value}">${safe(q)}<span aria-hidden="true">↗</span></button>`).join('');$('commonQuestions').querySelectorAll('button').forEach(b=>b.onclick=()=>{const q=b.textContent.replace(/↗$/,'').trim();if(q!==$('readingQuestion').value)invalidateQuestionEvents();$('readingQuestion').value=b.textContent.replace(/↗$/,'').trim();syncQuestionChoices()});}
function invalidateQuestionEvents(){coin=null;plum=null;tarotDrawn=null;generated=false;weightMode='auto';}
function startConsultation(){if(!dateParts($('dob').value)){focusBirthday();return false;}if(!$('readingQuestion').value.trim())$('readingQuestion').value=questionChoices()[0];renderQuick();const plan=window.FateInterpretation.recommend(readingContext(),{...lastComputed.ready,tarotDraw:true,iching:true,meihua:true});if(plan.weights.tarotDraw&&!tarotDrawn)drawTarot(3);if(plan.weights.iching&&!coin)castCoins();if(plan.weights.meihua&&!plum)castPlum();weightMode='auto';renderReport();return true;}
function initConsultation(){const year=Number(new Intl.DateTimeFormat('en',{timeZone:'Asia/Taipei',year:'numeric'}).format(new Date()));$('readingYear').innerHTML=Array.from({length:4},(_,i)=>`<option value="${year-1+i}" ${i===1?'selected':''}>${year-1+i} 年</option>`).join('');$('readingYear').value=String(year);$('readingQuestion').value=questionChoices()[0];document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{if($('topic').value===b.dataset.topic)return;invalidateQuestionEvents();$('topic').value=b.dataset.topic;$('readingQuestion').value=questionChoices()[0];updateTopicBrief()});$('readingYear').addEventListener('change',()=>{invalidateQuestionEvents();if($('topic').value==='year')$('readingQuestion').value=questionChoices()[0];updateTopicBrief();renderQuick()});$('consultStart').onclick=()=>showView('profile');updateTopicBrief();}
function initEdition(){initConsultation();$('birthBack').onclick=()=>finishBirthEditor();window.addEventListener?.('popstate',e=>{birthOrigin=null;applyRoute(e.state?.fateRoute||{view:'home'})}); $('heroSky').innerHTML=wheelArt();if($('startExplore'))$('startExplore').onclick=spinDiscovery;$('closeChart').onclick=closeReading;$('chartBack').onclick=closeReading;$('chartDialog').addEventListener('cancel',e=>{e.preventDefault();closeReading()});$('chartDialog').addEventListener('click',e=>{if(e.target===$('chartDialog')){const r=$('chartDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeReading();}});$('birthplace').addEventListener('change',()=>{const city=CITY[$('birthplace').value];if(city){$('latitude').value=city[0];$('longitude').value=city[1];$('birthtz').value=city[2]}renderQuick();if(generated)renderReport(false)});for(const id of ['latitude','longitude','timefold'])$(id).addEventListener('change',()=>{renderQuick();if(generated)renderReport(false)});$('atlasFilters').querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{atlasFilter=b.dataset.filter;for(const x of $('atlasFilters').querySelectorAll('button'))x.classList.toggle('active',x===b);renderVisuals(lastComputed)});$('menuToggle').onclick=()=>{const open=$('mainMenu').hidden;$('mainMenu').hidden=!open;$('menuToggle').setAttribute('aria-expanded',String(open))};document.addEventListener?.('keydown',e=>{if(e.key==='Escape'){$('mainMenu').hidden=true;$('menuToggle').setAttribute('aria-expanded','false')}});applyRoute({view:'home'});history.replaceState?.({...history.state,fateRoute:{view:'home',y:0,chart:null}},'',location.href);initDiscovery();initJourney();}

function ritualQueue(){const c=lastComputed;if(!c)return[];const plan=window.FateInterpretation.recommend(readingContext(),{...c.ready,tarotDraw:true,iching:true,meihua:true,liuyao:true});return [plan.weights.tarotDraw?{kind:'tarot',done:!!tarotDrawn}:null,(plan.weights.iching||plan.weights.liuyao)?{kind:'coin',done:!!coin}:null,plan.weights.meihua?{kind:'plum',done:!!plum}:null].filter(Boolean);}
function prepareJourney(){if(!dateParts($('dob').value)){focusBirthday();return false;}renderQuick();showView('ritual');return true;}
function renderRitual(){const queue=ritualQueue(),next=queue.find(e=>!e.done),done=queue.filter(e=>e.done).length;$('ritualQuestion').textContent=$('readingQuestion').value;$('ritualSkip').hidden=!next;
 const labels={tarot:['帶著問題，抽三張牌','抽三張牌 ✦'],coin:['帶著問題，擲一次卦','擲幣起卦 ☷'],plum:['留住此刻，起一個卦','現在起卦 ❋']};
 $('ritualTitle').textContent=next?labels[next.kind][0]:'準備好了，一起看解讀';$('ritualNext').textContent=next?labels[next.kind][1]:'看我的合參解讀 →';$('ritualHint').textContent=next?'想著這一題，準備好就開始。':'把你的資料與這次互動放在一起，看看各派怎麼說。';$('ritualSkip').textContent=done?'略過剩下的互動 →':'略過互動，直接看解讀 →';
 const cards=tarotDrawn?window.FateEngine.tarotView(tarotDrawn):[];
 $('ritualResult').innerHTML=cards.length?`<div class="journey-tarot">${cards.map((r,i)=>`<article class="journey-tarot-card"><small>${['背景','現在','方向'][i]||'提醒'}</small><span aria-hidden="true">${['☾','✦','☀'][i]||'✧'}</span><b>${safe(r.name)}</b><small>${r.reversed?'逆位':'正位'}</small></article>`).join('')}</div>`:'<div class="journey-tarot card-backs" aria-hidden="true"><i>☾</i><i>✦</i><i>☀</i></div>';
 if(coin)$('ritualResult').innerHTML+=`<div class="ritual-event">${uiHex(coin.lines)}<b>${safe(coin.primary.title)}</b></div>`;
 if(plum)$('ritualResult').innerHTML+=`<div class="ritual-event"><b>${safe(plum.primary.title)}</b></div>`;
 if(next&&next.kind!=='tarot'&&!cards.length&&!coin&&!plum)$('ritualResult').innerHTML='<div class="coin-symbol" aria-hidden="true">☷</div>';
}
function performRitual(){if(!dateParts($('dob').value))return focusBirthday();const next=ritualQueue().find(e=>!e.done);if(!next){weightMode='auto';renderReport();return true;}if(next.kind==='tarot')drawTarot(3);else if(next.kind==='coin')castCoins();else castPlum();generated=false;renderRitual();return true;}
function skipRitual(){if(!dateParts($('dob').value))return focusBirthday();weightMode='auto';renderReport();return true;}
function renderTakeaway(){if(!lastComputed||!generated)return;const r=window.FateInterpretation.consultation(lastComputed,readingContext(),{coin,plum,tarotDrawn},weights);$('finishQuestion').textContent=r.question;$('finishAction').textContent=r.first;$('finishWatch').textContent='留意：'+r.watch+'。';$('finishFeedback').textContent='';}
function initJourney(){$('consultStart').disabled=false;
 $('journeyBack').onclick=journeyBack;$('profileNext').onclick=prepareJourney;$('ritualNext').onclick=()=>gameAction(ritualQueue().find(e=>!e.done)?.kind||'report',$('ritualNext'),()=>{const result=performRitual();return result;});

 $('ritualSkip').onclick=()=>{if(!actionBusy)skipRitual();};$('reportNext').onclick=()=>showView('finish');$('finishSave').onclick=()=>{exportReport();$('finishFeedback').textContent='已準備下載，請查看瀏覽器的下載項目。';};$('finishShare').onclick=()=>{share();};$('finishPrint').onclick=()=>{$('printPdf').click();};$('askAnother').onclick=()=>showView('home');

}

const SCHOOL_CUES={western:'☉ 黃道十二星座',ziwei:'✶ 紫微星 · 十二宮',bazi:'甲子 · 四柱八字',vedic:'印度 · 恆星與月宿',iching:'☰ 六十四卦 · 變化',tarotDraw:'三張牌 · 問當下',numerology:'生日 → 生命道路數',meihua:'梅花 · 當下時刻起卦',liuyao:'三枚銅錢 · 六爻',nineStar:'九宮洛書 · 本命星',tarotBirth:'生日 → 大阿爾克那',maya:'馬雅 · 卓爾金曆'};
const SCHOOL_ART={western:'鈷藍桌布上的黃道十二星座盤',ziwei:'廟宇中的紫微大帝神像',bazi:'命理師排列四柱八字字牌',vedic:'印度占星師與菱形命盤',iching:'書桌上的易經卦象與蓍草',tarotDraw:'酒紅桌布上的三張塔羅牌',numerology:'手排木製數字牌',meihua:'書房中的梅花與手寫卦象',liuyao:'手擲銅錢與六爻卦紙',nineStar:'庭院石桌上的九宮洛書盤',tarotBirth:'生日曆與皇后大阿爾克那牌',maya:'真實考古場景風格的馬雅石碑與神廟'};
function focusBirthday(){showView('profile',false);$('dob').scrollIntoView({behavior:'smooth',block:'center'});$('dob').focus?.({preventScroll:true});$('dob').setAttribute?.('aria-invalid','true');$('birthHint').textContent='請先填寫有效的西元生日';$('birthHint').classList.toggle('input-error',true);gameToast('請先填寫生日');}
function updateWheelEligibility(c){const pool=c?window.FateDiscovery.eligible(c.ready):[];const caption=document.querySelector('.wheel-caption');if(caption)caption.textContent=c?`已開啟 ${pool.length} / 12 派 · 可用流派等機率`:'填好生日，按中央開始';document.querySelectorAll('[data-wheel-system]').forEach(el=>{const available=pool.includes(el.dataset.wheelSystem);el.style.opacity=c&&!available?'.28':'1';});if($('currentBirthday'))$('currentBirthday').textContent=c?.p.iso||'尚未填寫';}
function runReading(id){const kind=window.FateDiscovery.actionFor(id);if(kind==='tarot'){const old=tarotDrawn;drawTarot(3);if(tarotDrawn===old)throw Error('抽牌未完成，請再試一次');}else if(kind==='coin'){const old=coin;castCoins();if(coin===old)throw Error('起卦未完成，請再試一次');}else if(kind==='plum'){const old=plum;castPlum();if(plum===old)throw Error('起卦未完成，請再試一次');}else renderQuick();if(!lastComputed?.ready[id])throw Error('資料尚未完整，請補上出生時地');return lastComputed;}
function readingSummary(id,c){const numWords=['','開創與自主','合作與感受','表達與創作','秩序與累積','變化與自由','照顧與責任','探索與思考','組織與實踐','理解與分享'];let title='',detail='',note='依生日計算；象徵解讀供自我觀察。';switch(id){case 'western':title=`太陽${c.sun||'星座待確認'}`;detail=c.sky.status==='ok'?`月亮 ${SKY().signText(c.sky.points[1].lon)}${c.sky.axes?' · 上升 '+SKY().signText(c.sky.axes.asc):' · 上升需出生座標'}`:'這是太陽星座日期摘要。完整行星、月亮與上升，需補上出生時地。';break;case 'vedic':title=c.sky.status==='ok'?c.sky.vedic.nakshatra:`恆星太陽${c.vedic||'星座待確認'}`;detail=c.sky.status==='ok'?`第 ${c.sky.vedic.pada} 足 · 月宿主星 ${c.sky.vedic.lord}`:'目前為恆星太陽日期摘要；月宿與分盤需出生時間及時區。';note='採近似 Lahiri 歲差；交界需以專業星曆複核。';break;case 'ziwei':{const palace=c.ziwei.palaces?.find(p=>p.name.includes('命'));title=palace?`命宮 · ${palace.stem}${palace.branch}`:'紫微命盤待解鎖';detail=palace?`主星：${palace.stars.map(x=>x.name).join('、')||'無主星，需合看對宮'}。十二宮完整星曜可展開查看。`:c.ziwei.reason;break;}case 'bazi':title=`日主 · ${c.bazi.dayMaster}`;detail=`${c.bazi.year||'年柱待確認'} · ${c.bazi.month||'月柱待確認'} · ${c.bazi.day}${c.baziExtra?.hour?' · '+c.baziExtra.hour:' · 時柱未提供'}`;note='依節氣排柱，採民用時間零時換日；未校正真太陽時。';break;case 'numerology':title=`生命道路數 ${c.num.life}`;detail=`傳統象徵：${numWords[c.num.life]}。生日數 ${c.num.birthday} · 態度數 ${c.num.attitude}。`;note='把這個象徵當作提問：最近的生活中，你在哪裡看見這個主題？';break;case 'nineStar':title=c.nine?.name||'節氣待確認';detail=`本命星 ${c.nine?.star||'—'} · 月命 ${c.nine?.monthName||'待確認'} · 當年中宮 ${c.nine?.annual||'—'}`;note='以立春換年、節氣換月；九宮方向為南上北下。';break;case 'tarotBirth':title=TAROT_NAMES[c.tarot.major%22];detail=`你的生日主牌是「${title}」，靈魂牌是「${TAROT_NAMES[c.tarot.minor%22]}」。${c.tarot.calc}。`;note='由生日歸約得到，與隨機抽牌分開計算。';break;case 'maya':title=c.my.tz;detail=`長紀曆 ${c.my.long} · Haab ${c.my.haab}`;note='採傳統 GMT 584283 曆法對應，不混用 Dreamspell。';break;case 'tarotDraw':{const cards=tarotDrawn?window.FateEngine.tarotView(tarotDrawn):[];title=cards.map(x=>x.name).join(' · ')||'尚未抽牌';detail=`本次從 78 張牌中獨立抽出 ${tarotDrawn?.spread||0} 張，牌位與牌義如下。`;note=tarotDrawn?'抽牌時刻 '+tarotDrawn.time:'先完成抽牌';break;}case 'meihua':title=plum?.primary.title||'尚未起卦';detail=plum?`第 ${plum.move} 爻動 · 之卦 ${plum.changed.title} · 體 ${plum.move<=3?plum.up:plum.low}／用 ${plum.move<=3?plum.low:plum.up}`:'以當下農曆時刻起卦。';note=plum?'起卦時刻 '+plum.time+' · 臺北時間算法':'尚未起卦';break;default:title=coin?.primary.title||'尚未起卦';detail=coin?`動爻 ${coin.moving.length?coin.moving.join('、'):'無'} · 之卦 ${coin.changed.title}`:'以三枚銅錢擲六次起卦。';note=coin?'起卦時刻 '+coin.time+' · 隨機事件，與生日獨立':'尚未起卦';}return {title,detail,note};}
function updateTopicBrief(){if($('topicBrief'))$('topicBrief').textContent=window.FateInterpretation.TOPICS[$('topic').value]||'近期方向';syncQuestionChoices();}
function readingContext(){return window.FateInterpretation.context({topic:$('topic').value,question:$('readingQuestion').value,year:$('readingYear').value,weightMode});}
function interpreted(id,c){return window.FateInterpretation.interpret(id,c,readingContext(),{coin,plum,tarotDrawn});}
function interpretationReport(c){return window.FateInterpretation.renderReport(window.FateInterpretation.report(c,readingContext(),{coin,plum,tarotDrawn},weights));}
function readingMarkup(id,c){const m=COLLECTION.find(x=>x.id===id),r=readingSummary(id,c),reading=interpreted(id,c);return `<figure class="reading-cover"><img src="./assets/schools/${id}.webp" alt="${safe(SCHOOL_ART[id])}" width="1200" height="800"><figcaption><small>${m.latin}</small><strong>${m.name}</strong></figcaption></figure><div class="reading-context-bar"><span>${safe(window.FateInterpretation.TOPICS[reading.topic])} · ${['iching','meihua','liuyao','tarotDraw'].includes(id)?'本次事件解讀':safe(c.p.iso)}</span><button type="button" data-edit-question>換個問題 ↗</button></div><div data-reading-system="${id}">${window.FateInterpretation.render(reading)}</div>${!c.ready[id]?'<div class="reading-unlock"><button class="btn btn-primary" data-edit-birth>補上出生資料，解鎖命盤 ↗</button></div>':''}<details class="reading-details raw-reading"><summary>命盤與詳細計算</summary><div><h3>${safe(r.title)}</h3><p>${safe(r.detail)}</p><small>${safe(r.note)}</small><div class="reading-diagram">${visualFor(id,c)}</div>${chartDetails(id,c)}</div></details>${id==='tarotDraw'?`<details class="reading-tools"><summary>調整牌陣或重新抽牌</summary><p class="detail-note">同一題不必反覆重抽；先保存本次結果，再核對新增資訊。</p><div class="dialog-actions"><button class="btn btn-soft" data-dialog-draw="1">單張牌</button><button class="btn btn-primary" data-dialog-draw="3">三張牌</button><button class="btn btn-soft" data-dialog-draw="10">塞爾特十字</button></div></details>`:''}<div class="reading-next"><button type="button" class="btn btn-primary" data-full-reading>看各派合參 ↗</button><button type="button" class="btn btn-soft" data-read-again>換一派參照 ↻</button></div>`;}


// PRISM / physical wheel, optional gesture-triggered audio and an exploration album.
let wheelRotation=0,wheelBusy=false,wheelPick=null,actionBusy=false,soundEnabled=true,audioContext=null,toastTimer;
const explored=new Set();
try{soundEnabled=localStorage.getItem('fate-atlas-sound')!=='off';const saved=JSON.parse(localStorage.getItem('fate-atlas-explored-v23')||'[]');if(Array.isArray(saved))saved.filter(x=>COLLECTION.some(m=>m.id===x)).forEach(x=>explored.add(x));}catch{}
function gameSound(kind='tap'){
 if(!soundEnabled)return;
 try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!audioContext)audioContext=new Audio();if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});const now=audioContext.currentTime;
  const note=(freq,at,length,volume,type='sine')=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type;o.frequency.setValueAtTime(freq,at);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(volume,at+.005);g.gain.exponentialRampToValueAtTime(.0001,at+length);o.connect(g);g.connect(audioContext.destination);o.onended=()=>{o.disconnect();g.disconnect();};o.start(at);o.stop(at+length+.02);};
  if(kind==='tick')note(240,now,.035,.045,'triangle');else if(kind==='win'){[523.25,659.25,783.99].forEach((n,i)=>note(n,now+i*.11,.5,.065));note(1046.5,now+.32,.65,.035);}else note(392,now,.1,.035,'triangle');
 }catch{/* Audio support never blocks an interaction. */}
}
function updateSound(){const b=$('soundToggle');b.textContent=soundEnabled?'♪ 音效開':'♪ 音效關';b.setAttribute?.('aria-pressed',String(soundEnabled));b.setAttribute?.('aria-label',soundEnabled?'關閉音效':'開啟音效');}
function gameToast(message){const el=$('gameToast');if(!el)return;clearTimeout(toastTimer);const host=$('chartDialog').open?$('chartDialog'):document.body;host.appendChild(el);el.textContent=message;el.classList.toggle('show',true);toastTimer=setTimeout(()=>el.classList.toggle('show',false),2600);}
function updateDiscovery(){const n=explored.size;$('exploredCount').textContent=n;$('explorerLevel').textContent='探索 Lv.'+(1+Math.floor(n/3));$('discoveryBar').style.width=(n/12*100)+'%';$('discoveryBadges').innerHTML=COLLECTION.map((m,i)=>`<span class="discovery-gem ${explored.has(m.id)?'collected':''}" title="${safe(m.name)}${explored.has(m.id)?' · 已探索':''}">${String(i+1).padStart(2,'0')}</span>`).join('');}
function recordExplore(id){if(explored.has(id))return;explored.add(id);try{localStorage.setItem('fate-atlas-explored-v23',JSON.stringify([...explored]));}catch{}updateDiscovery();gameSound('win');gameToast('✦ 圖鑑 +1 · '+COLLECTION.find(m=>m.id===id).name);const card=document.querySelector('[data-chart="'+id+'"]');if(card&&!card.querySelector('.explored-label')){const badge=document.createElement('span');badge.className='explored-label';badge.textContent='✦ 已探索';card.appendChild(badge);}}
function wheelArt(){const palette=['#285ba1','#704388','#97512f','#b26a0c','#344a78','#883751','#6b4298','#9a384b','#a63e2f','#387345','#ac5674','#16796c'];const short=['西洋占星','紫微斗數','八字四柱','印度占星','易經卦象','傳統塔羅','生命靈數','梅花易數','六爻納甲','九星氣學','生日塔羅','馬雅曆法'];const icons=['☉','✶','☯','✦','☰','✧','❖','❋','☷','✻','✵','◈'];const xy=(a,r)=>[220+r*Math.cos((a-90)*Math.PI/180),220+r*Math.sin((a-90)*Math.PI/180)];let sectors='';for(let i=0;i<12;i++){const a=xy(i*30,198),b=xy((i+1)*30,198),mid=i*30+15,label=xy(mid,153),icon=xy(mid,105);sectors+=`<path data-wheel-system="${COLLECTION[i].id}" d="M220 220L${a[0]} ${a[1]}A198 198 0 0 1 ${b[0]} ${b[1]}Z" fill="${palette[i]}" stroke="#f5d9a9" stroke-width=".9"/><text x="${label[0]}" y="${label[1]}" transform="rotate(${mid} ${label[0]} ${label[1]})" text-anchor="middle" fill="#fff6df" font-size="14.5" font-weight="600" letter-spacing=".4">${short[i]}</text><text x="${icon[0]}" y="${icon[1]+5}" text-anchor="middle" fill="#ffe9bf" font-size="21">${icons[i]}</text>`;}const studs=Array.from({length:24},(_,i)=>{const p=xy(i*15,210);return `<circle cx="${p[0]}" cy="${p[1]}" r="2" fill="#f4e1b1" opacity=".8"/>`}).join('');return `<div class="wheel-scene"><div class="wheel-orbit orbit-a"></div><div class="wheel-orbit orbit-b"></div><span class="wheel-spark spark-a">✦</span><span class="wheel-spark spark-b">✧</span><div class="wheel-pointer" aria-hidden="true"><i id="wheelPin"></i></div><div class="wheel-frame"><div class="wheel-rotor" id="wheelRotor"><svg viewBox="0 0 440 440" aria-hidden="true"><defs><radialGradient id="wheelLight"><stop stop-color="#fff" stop-opacity=".15"/><stop offset=".65" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#1c1642" stop-opacity=".24"/></radialGradient></defs><circle cx="220" cy="220" r="218" fill="#9d774b"/>${sectors}<circle cx="220" cy="220" r="198" fill="url(#wheelLight)"/><g fill="none" stroke="#f6e2b7"><circle cx="220" cy="220" r="201" stroke-width="3"/><circle cx="220" cy="220" r="215" stroke-width="1"/><circle cx="220" cy="220" r="134" opacity=".25"/><circle cx="220" cy="220" r="79" opacity=".5"/></g>${studs}</svg></div><div class="wheel-gloss" aria-hidden="true"></div><button class="wheel-center" id="wheelSpin" aria-label="轉出一派並為我解讀"><span>✦</span><b>隨機一派</b><small>FATE ATLAS</small></button></div><div class="wheel-plinth" aria-hidden="true"></div></div><div class="wheel-controls"><span class="wheel-caption">也可以轉輪盤，隨機看一派</span><button class="sound-toggle" id="soundToggle" type="button">♪ 音效開</button></div><div class="wheel-result" id="wheelResult" aria-live="polite"><span>選好問題，轉一派來看。</span></div>`;}
function spinDiscovery(){if(wheelBusy)return;if(!dateParts($('dob').value)){focusBirthday();return;}renderQuick();const D=window.FateDiscovery,pool=D.eligible(lastComputed.ready);let p;try{if(!pool.length)throw Error('請先補齊出生資料');const id=pool[D.randomIndex(pool.length)];p=D.plan(D.ids.indexOf(id),wheelRotation,5,(D.randomIndex(1001)/1000-.5)*18);}catch(e){gameToast(String(e.message||e));return;}wheelBusy=true;const spinView=currentView;gameSound('tap');const buttons=[$('wheelSpin'),$('startExplore'),$('spinAgain')].filter(Boolean),fields=['dob','birthtime','birthtz','gender','birthplace','latitude','longitude','timefold'].map($);buttons.forEach(b=>{b.disabled=true;b.setAttribute?.('aria-busy','true')});fields.forEach(b=>b.disabled=true);$('wheelSpin').querySelector('b').textContent='解讀中';$('wheelResult').innerHTML='<span class="wheel-searching">正在為你選出一個視角…</span>';$('heroSky').classList.toggle('is-spinning',true);const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,duration=reduced?350:4000,start=performance.now(),rotor=$('wheelRotor');let previousTick=Math.floor(wheelRotation/30),lastTickTime=0;const frame=now=>{if(currentView!==spinView){wheelBusy=false;$('heroSky').classList.toggle('is-spinning',false);buttons.forEach(b=>{b.disabled=false;b.setAttribute?.('aria-busy','false')});fields.forEach(b=>b.disabled=false);syncJourney();return;}const t=Math.min(1,(now-start)/duration),ease=1-Math.pow(1-t,4),rotation=reduced?p.target:p.start+(p.target-p.start)*ease;rotor.style.transform=`rotate(${rotation}deg)`;const tick=Math.floor(rotation/30);if(!reduced&&tick!==previousTick&&now-lastTickTime>28){previousTick=tick;lastTickTime=now;gameSound('tick');$('wheelPin').animate?.([{transform:'rotate(-13deg)'},{transform:'rotate(0deg)'}],{duration:120,easing:'ease-out'})}if(t<1){requestAnimationFrame(frame);return;}wheelRotation=p.target;wheelPick=p.id;$('heroSky').classList.toggle('is-spinning',false);try{runReading(p.id);const m=COLLECTION.find(x=>x.id===p.id);$('wheelResult').innerHTML=`<div class="wheel-selection"><span>本次解讀已完成</span><b>${m.name}</b></div><button class="result-reopen" id="reopenReading">查看解讀 ↗</button>`;$('wheelResult').dataset.system=p.id;$('reopenReading').onclick=()=>openChart(p.id);gameSound('win');openChart(p.id)}catch(e){gameToast(String(e.message||e));$('wheelResult').textContent='這次未能完成，請再試一次。'}finally{wheelBusy=false;buttons.forEach(b=>{b.disabled=false;b.setAttribute?.('aria-busy','false')});fields.forEach(b=>b.disabled=false);$('wheelSpin').querySelector('b').textContent='再轉一派';}};requestAnimationFrame(frame);}
function gameAction(kind,button,action){if(actionBusy)return;actionBusy=true;const actionRoute=currentView;const label=button?.innerHTML,words={report:'正在解讀…',coin:'銅錢起落中…',plum:'正在捕捉此刻…',tarot:'正在洗牌…'};if(button){button.disabled=true;button.classList.toggle('is-loading',true);button.setAttribute?.('aria-busy','true');button.textContent=words[kind]||'準備中…';}gameSound('tap');setTimeout(()=>{try{if(currentView!==actionRoute)return;const outcome=action();if(outcome===false){gameToast('先補上有效資料，再展開這次探索');return;}gameSound('win');gameToast({report:'解讀完成',coin:'☷ 六爻已成，點開看看',plum:'❋ 此刻的梅花卦已展開',tarot:'✧ 牌陣已揭曉'}[kind]||'已完成');}catch(err){gameToast('這次未能完成，請再試一次');}finally{actionBusy=false;if(button){button.disabled=false;button.classList.toggle('is-loading',false);button.setAttribute?.('aria-busy','false');button.innerHTML=label;if(button.id==='ritualNext'&&currentView==='ritual')renderRitual();}}},kind==='tarot'?650:kind==='coin'?750:350);}
function initDiscovery(){$('brandMeaning').onclick=()=>{$('chartDialog').dataset.system='meaning';$('chartTitle').textContent='合參 · FATE ATLAS';$('chartBody').innerHTML='<div class="detail-lead">不同的智慧，放在同一張圖譜。</div><p class="detail-note">「合參」意指整合不同流派，互相參照與探究。FATE 是命運，ATLAS 是圖譜；合起來，可理解為「命運圖譜」。</p><div class="meaning-grid"><div><b>合</b><span>整合不同文明的命理智慧</span></div><div><b>參</b><span>互相參照、比較與探究</span></div><div><b>ATLAS</b><span>每個流派，都是一個探索入口</span></div></div>';$('chartDialog').showModal();};updateSound();updateDiscovery();$('wheelSpin').onclick=()=>showView('profile');$('soundToggle').onclick=()=>{soundEnabled=!soundEnabled;try{localStorage.setItem('fate-atlas-sound',soundEnabled?'on':'off');}catch{}updateSound();if(soundEnabled)gameSound('tap');};$('spinAgain').textContent='隨機看一派 ↻';$('spinAgain').onclick=()=>{if(!lastComputed){focusBirthday();return;}spinDiscovery();};$('browseAlbum').textContent='回到本次解讀 →';$('browseAlbum').onclick=()=>generated?showView('report'):showView('home');document.addEventListener?.('click',e=>{const b=e.target.closest?.('button');if(b&&!b.disabled&&!['wheelSpin','startExplore','spinAgain','soundToggle'].includes(b.id)&&!b.dataset.open)gameSound('tap');});}

