function extendedReport(c){const s=c.sky;let html='';if(s.status==='ok'&&(weights.western>0||weights.vedic>0)){html+=`<section class="report-block"><h3>你的行星星圖</h3><p class="muted smalltxt">UTC ${safe(s.utc)} · ${safe(s.civil.timezone)} · ${safe(s.locationReason)}。Lahiri 歲差為近似模型。</p><div class="report-atlas"><div><b>西洋 · 熱帶黃道</b>${wheel(c,'western',true)}</div><div><b>印度 · 恆星黃道</b>${wheel(c,'vedic',true)}</div></div>${table(['行星','熱帶黃道','恆星黃道','整宮'],s.points.map(p=>[p.glyph+' '+p.name,SKY().signText(p.lon),SKY().signText(p.sidereal),p.house||'需座標']))}<h3>本命相位</h3>${table(['行星 A','相位','行星 B','容許度'],s.aspects.map(a=>[a.a,a.name,a.b,a.orb.toFixed(2)+'°']))}<h3>印度 D9 與大運</h3>${table(['行星','D9 Navamsa'],s.points.slice(0,7).map(p=>[p.name,SKY().signText(p.navamsa)]))}${table(['Vimshottari','起始','結束'],s.vedic.dasha.map(p=>[p.lord,p.start,p.end]))}<p class="muted smalltxt">大運採 365.2425 天／年；月宿、Pada 和大運日期均受近似歲差影響，交界需複核。</p></section>`;}if(c.luck&&weights.bazi>0)html+=`<section class="report-block"><h3>八字大運 · ${c.luck.forward?'順':'逆'}行</h3><p>約 ${c.luck.age.toFixed(2)} 歲起運，按三天折一歲。</p>${table(['大運','起始年齡','結束年齡'],c.luck.periods.map(p=>[p.pillar,p.from.toFixed(2),p.to.toFixed(2)]))}</section>`;return html;}

function navigation(){document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.nav==='weights'&&!lastComputed){focusBirthday();return;}if(b.dataset.nav==='report'&&!generated){if(!dateParts($('dob').value)){focusBirthday();return;}prepareJourney();return;}showView(b.dataset.nav)}))}
document.querySelectorAll('button[data-draw]').forEach(el=>el.addEventListener('click',()=>gameAction('tarot',el,()=>drawTarot(Number(el.dataset.draw)))));
['birthtime','birthtz','gender'].forEach(id=>$(id).addEventListener('change',()=>{renderQuick();if(generated)renderReport(false)}));
